from pathlib import Path
import difflib
lines = Path('evidence/coder-before.txt').read_text(encoding='utf-8-sig').splitlines(keepends=True)
before = {}
current = None
for line in lines:
    if line.startswith('SHA256 '):
        current = None
    elif line.startswith('FILE '):
        current = line[5:].strip()
        before[current] = []
    elif current:
        before[current].append(line)
diff = []
for relative, original in before.items():
    diff.extend(difflib.unified_diff(original, Path(relative).read_text(encoding='utf-8').splitlines(keepends=True), fromfile=f'before/{relative}', tofile=f'after/{relative}'))
Path('evidence/coder-diff.patch').write_text(''.join(diff), encoding='utf-8')
